   // type and payload separate
   <K extends keyof M>(
     type: K,
     payload: Payload<M[K]>,
     options?: CommitOptions
   ): void
   // type part of payload
   <K extends keyof M>(
     payload: Payload<M[K]> & { type: K },
     options?: CommitOptions
   ): void
   // no payload (only mutations without parameters)
   <K extends { [K in keyof M]: M[K] extends () => any ? K : never }[keyof M]>(
     type: K
   ): void
