 import { Context, Commit, Dispatch, createLazyContextPosition } from './context'
 import { ComponentMapper, MappedFunction, RestArgs } from './mapper'

 export interface ModuleOptions<
   S,
   G extends BG<S>,
   M extends BM<S>,
   A extends BA<S, G, M>
