   mapState<T extends Record<string, keyof S>>(
     map: T
   ): { [Key in keyof T]: () => S[T[Key] & keyof S] }
   mapState<T extends Record<string, (state: S, getters: G) => any>>(
     map: T
   ): { [Key in keyof T]: () => ReturnType<T[Key]> }
