     const pos = this.pos

     return createMappedObject(map, value => {
       return function mappedMutationMethod(this: Vue, ...args: any[]) {
         const commit = (type: any, payload: any) => {
           return namespacedCommit(this.$store, pos.namespace, type, payload)
