 function createMappedObject(
   map: string[] | Record<string, any>,
   fn: (value: any) => any
 ): Record<string, any> {
   const normalized = !Array.isArray(map)
     ? map
     : map.reduce<Record<string, string>>((acc, key) => {
         acc[key] = key
         return acc
       }, {})
