32. export class ComponentMapper<
33.   S,
34.   G extends BG<S>,
35.   M extends BM<S>,
36.   A extends BA<S, G, M>
37. > {
38.   constructor(private pos: ContextPosition) {}
39. 
40.   mapState<K extends keyof S>(map: K[]): { [Key in K]: () => S[Key] }
41.   mapState<T extends Record<string, keyof S>>(
42.     map: T
43.   ): { [Key in keyof T]: () => S[T[Key] & keyof S] }
44.   mapState<T extends Record<string, (state: S, getters: G) => any>>(
45.     map: T
46.   ): { [Key in keyof T]: () => ReturnType<T[Key]> }
47.   mapState(map: any): { [key: string]: () => any } {
48.     const pos = this.pos
49. 
50.     return createMappedObject(map, value => {
51.       return function mappedStateComputed(this: Vue) {
52.         const state = get(pos.path, this.$store.state)
53. 
54.         if (typeof value === 'function') {
55.           const getters = namespacedGetters(this.$store, pos.namespace)
56.           return value.call(this, state, getters)
57.         } else {
58.           return state[value]
59.         }
60.       }
61.     })
62.   }
63. 
64.   mapGetters<K extends keyof G>(map: K[]): { [Key in K]: () => G[Key] }
65.   mapGetters<T extends Record<string, keyof G>>(
66.     map: T
67.   ): { [Key in keyof T]: () => G[T[Key] & keyof G] }
68.   mapGetters(map: any): { [key: string]: () => any } {
69.     const pos = this.pos
70. 
71.     return createMappedObject(map, value => {
72.       function mappedGetterComputed(this: Vue) {
73.         return this.$store.getters[pos.namespace + value]
74.       }
75. 
76.       // mark vuex getter for devtools
77.       mappedGetterComputed.vuex = true
78. 
79.       return mappedGetterComputed
