91.   >(
92.     map: T
93.   ): { [Key in keyof T]: (...args: RestArgs<T[Key]>) => ReturnType<T[Key]> }
94.   mapMutations(map: any): { [key: string]: (...args: any[]) => any } {
95.     const pos = this.pos
96. 
97.     return createMappedObject(map, value => {
98.       return function mappedMutationMethod(this: Vue, ...args: any[]) {
99.         const commit = (type: any, payload: any) => {
100.           return namespacedCommit(this.$store, pos.namespace, type, payload)
101.         }
102. 
103.         return typeof value === 'function'
104.           ? value.apply(this, [commit].concat(args))
105.           : commit(value, args[0])
106.       }
107.     })
108.   }
109. 
110.   mapActions<K extends keyof A>(
111.     map: K[]
112.   ): { [Key in K]: MappedFunction<A[Key], Promise<any>> }
113.   mapActions<T extends Record<string, keyof A>>(
114.     map: T
115.   ): { [Key in keyof T]: MappedFunction<A[T[Key] & keyof A], Promise<any>> }
116.   mapActions<
117.     T extends Record<string, (dispatch: Dispatch<A>, ...args: any[]) => any>
118.   >(
119.     map: T
120.   ): { [Key in keyof T]: (...args: RestArgs<T[Key]>) => ReturnType<T[Key]> }
121.   mapActions(map: any): { [key: string]: (...args: any[]) => any } {
122.     const pos = this.pos
123. 
124.     return createMappedObject(map, value => {
125.       return function mappedActionMethod(this: Vue, ...args: any[]) {
126.         const dispatch = (type: any, payload: any) => {
127.           return namespacedDispatch(this.$store, pos.namespace, type, payload)
128.         }
129. 
