138. function createMappedObject(
139.   map: string[] | Record<string, any>,
140.   fn: (value: any) => any
141. ): Record<string, any> {
142.   const normalized = !Array.isArray(map)
143.     ? map
144.     : map.reduce<Record<string, string>>((acc, key) => {
145.         acc[key] = key
146.         return acc
147.       }, {})
